# ============================================================================
# build-vista360.ps1 - Vista360 Local offline single-file builder
# Restores the full active project and also writes Vista360-Local.zip.
# Excludes only node_modules (reinstalled automatically) and data/trash.
# Compatible with Windows PowerShell 5.1 and PowerShell 7.
# IMPORTANT: Contains panorama data, account hashes, and local TLS keys.
# ============================================================================
param(
  [string]$Destination = (Get-Location).Path,
  [switch]$Force
)

$ErrorActionPreference = 'Stop'
$projectName = 'Vista360-Local'
$destinationRoot = [System.IO.Path]::GetFullPath($Destination)
$projectRoot = Join-Path $destinationRoot $projectName
$zipPath = Join-Path $destinationRoot 'Vista360-Local.zip'
$expectedArchiveHash = 'd3251082bced915b15310bf441d4a149b9d6049e13d792c02f4ddff4540471a8'
$expectedFileCount = 181

if (-not (Test-Path -LiteralPath $destinationRoot)) {
  New-Item -ItemType Directory -Path $destinationRoot -Force | Out-Null
}
if ((Test-Path -LiteralPath $projectRoot) -or (Test-Path -LiteralPath $zipPath)) {
  if (-not $Force) { throw "Vista360-Local or Vista360-Local.zip already exists in $destinationRoot. Choose another folder or use -Force." }
  if (Test-Path -LiteralPath $projectRoot) { Remove-Item -LiteralPath $projectRoot -Recurse -Force }
  if (Test-Path -LiteralPath $zipPath) { Remove-Item -LiteralPath $zipPath -Force }
}

Write-Host "`nVista360 Local builder - restoring project..." -ForegroundColor Cyan
