$sha256 = [System.Security.Cryptography.SHA256]::Create()
try { $actualHash = ([System.BitConverter]::ToString($sha256.ComputeHash($archiveBytes))).Replace('-', '').ToLowerInvariant() }
finally { $sha256.Dispose() }
if ($actualHash -ne $expectedArchiveHash) { throw 'Embedded archive integrity check failed.' }
[System.IO.File]::WriteAllBytes($zipPath, $archiveBytes)
$archiveBytes = $null
$payload = $null
[GC]::Collect()

Add-Type -AssemblyName System.IO.Compression.FileSystem
